<?php
declare(strict_types=1);
namespace InvoiceDesk;
final class Archive {
    public function __construct(private Service $s=new Service()){}
    private function dir(): string {$p=config()['storage'].'/archives';if(!is_dir($p))mkdir($p,0700,true);return $p;}
    public function path(string $id): string {if(!preg_match('/^[a-f0-9]{24}$/D',$id))throw new \InvalidArgumentException('Invalid archive ID.');return $this->dir().'/'.$id.'.zip';}
    public function pdf(int $id): array {
        $row=db()->one('SELECT * FROM invoices WHERE id=?',[$id]);if(!$row)throw new \RuntimeException('Invoice not found.');
        $dir=config()['storage'].'/pdf';if(!is_dir($dir))mkdir($dir,0700,true);
        $r=db()->one('SELECT * FROM pdfs WHERE invoice_id=?',[$id]);
        if($r && $r['source_hash']===$row['source_hash'] && is_file($r['path']) && hash_file('sha256',$r['path'])===$r['sha256'])return $r;
        $bytes=$this->s->bridge()->call('pdf',['invoice_id'=>$id],true);$path=$dir.'/'.$id.'-'.hash('sha256',$bytes).'.pdf';
        if(file_put_contents($path,$bytes,LOCK_EX)!==strlen($bytes))throw new \RuntimeException('Could not save PDF. Check free disk space.');@chmod($path,0600);
        if($r && $r['path']!==$path && is_file($r['path']))unlink($r['path']);
        $r=['invoice_id'=>$id,'path'=>$path,'sha256'=>hash('sha256',$bytes),'source_hash'=>$row['source_hash'],'fetched_at'=>now(),'size'=>strlen($bytes)];
        db()->run('INSERT INTO pdfs(invoice_id,path,sha256,source_hash,fetched_at,size) VALUES(?,?,?,?,?,?) ON CONFLICT(invoice_id) DO UPDATE SET path=excluded.path,sha256=excluded.sha256,source_hash=excluded.source_hash,fetched_at=excluded.fetched_at,size=excluded.size',array_values($r));
        return $r;
    }
    public function add(string $job,int $id,string $format): void {
        if(!class_exists('ZipArchive'))throw new \RuntimeException('Enable the PHP zip extension for bulk downloads.');
        $row=db()->one('SELECT * FROM invoices WHERE id=?',[$id]);if(!$row)throw new \RuntimeException('Invoice not found.');
        $name='invoices/'.$id.'-'.substr(preg_replace('/[^a-zA-Z0-9._-]/','_',$row['number']),0,80).'.'.$format;
        $pdf=$format==='pdf'?$this->pdf($id):null;
        $z=new \ZipArchive();if($z->open($this->path($job),\ZipArchive::CREATE)!==true)throw new \RuntimeException('Cannot create archive.');
        try{$ok=$pdf?$z->addFile($pdf['path'],$name):$z->addFromString($name,InvoiceView::html($row));if(!$ok)throw new \RuntimeException('Could not add invoice to archive.');}
        finally{if(!$z->close())throw new \RuntimeException('Could not write archive. Check free disk space.');}
    }
    public function finish(string $job,string $format): void {
        $tasks=db()->all('SELECT t.record_id,t.state,t.error,i.number,i.currency,i.total,i.tax,i.tax2,i.gstin,i.gst_status,i.fetched_at,p.sha256,p.fetched_at AS pdf_fetched FROM tasks t LEFT JOIN invoices i ON i.id=t.record_id LEFT JOIN pdfs p ON p.invoice_id=t.record_id WHERE t.job_id=? ORDER BY t.record_id',[$job]);
        $f=fopen('php://temp','w+');fputcsv($f,['Invoice ID','Number','Result','Error','Currency','Total','Tax','Recipient GSTIN','GSTIN check','Data fetched','PDF fetched','PDF SHA256'],',','"','');
        foreach($tasks as $t){$r=[$t['record_id'],$t['number'],$t['state'],$t['error'],$t['currency'],Money::decimal((int)$t['total']),Money::decimal((int)$t['tax']+(int)$t['tax2']),$t['gstin'],$t['gst_status'],$t['fetched_at'],$format==='pdf'?$t['pdf_fetched']:'',$format==='pdf'?$t['sha256']:''];fputcsv($f,array_map([Report::class,'csvCell'],$r),',','"','');}rewind($f);$csv=stream_get_contents($f);fclose($f);
        $z=new \ZipArchive();if($z->open($this->path($job),\ZipArchive::CREATE)!==true)throw new \RuntimeException('Cannot finalize archive.');
        $z->addFromString('manifest.csv',$csv);$z->addFromString('README.txt',"InvoiceDesk export\nGenerated: ".now()."\nFormat: ".$format."\nSee manifest.csv for every success and failure. A partial archive is not a complete invoice set.\nPDFs are generated by WHMCS at fetch time; HTML files are administrative cached copies.\nGSTIN regex/checksum checks do not confirm GST registration or legal tax treatment.\n");
        if(!$z->close())throw new \RuntimeException('Cannot finalize archive.');
    }
    public function verifyPdf(int $id): array {
        $bin=config()['pdftotext']??'';
        if(!$bin || !is_executable($bin) || !function_exists('proc_open'))throw new \RuntimeException('Configure pdftotext and enable proc_open to check actual PDF text.');
        $r=$this->pdf($id);$tmp=tempnam(config()['storage'],'text-');
        try{
            $pipes=[];$p=proc_open([$bin,'-layout','-enc','UTF-8',$r['path'],$tmp],[0=>['pipe','r'],1=>['file','/dev/null','w'],2=>['file','/dev/null','w']],$pipes);
            if(!is_resource($p))throw new \RuntimeException('PDF text extraction could not start.');fclose($pipes[0]);$start=microtime(true);$last=null;
            do{$last=proc_get_status($p);if(!$last['running'])break;usleep(20000);}while(microtime(true)-$start<8);
            if($last['running']){proc_terminate($p,9);proc_close($p);throw new \RuntimeException('PDF extraction timed out.');}
            $exit=proc_close($p);if(($last['exitcode']??$exit)!==0)throw new \RuntimeException('PDF text extraction failed.');
            if(filesize($tmp)>2097152)throw new \RuntimeException('Extracted text exceeds the safe limit.');
            $text=(string)file_get_contents($tmp);$all=Gst::extract($text);$supplier=strtoupper($this->s->settings()['supplier_gstin']??'');$candidates=array_values(array_filter($all,fn($x)=>$x!==$supplier));
            $check=['source_hash'=>$r['source_hash'],'sha256'=>$r['sha256'],'checked_at'=>now(),'matches'=>$all,'recipient_candidates'=>$candidates,'validations'=>array_map([Gst::class,'validate'],$candidates),'result'=>$supplier===''?'supplier_not_configured':(count($candidates)===1?'one_candidate':(count($candidates)>1?'ambiguous':'not_found')),'note'=>'Text match only. Visually confirm the candidate belongs to the recipient; image-only PDFs need manual inspection.'];
            db()->run('UPDATE invoices SET pdf_check=? WHERE id=?',[json_encode($check),$id]);return $check;
        } finally{if(is_file($tmp))unlink($tmp);}
    }
    public function prune(): int {
        $days=max(1,(int)$this->s->settings()['archive_days']);$cut=time()-$days*86400;$n=0;
        foreach(glob($this->dir().'/*.zip')?:[] as $p)if(filemtime($p)<$cut){$id=basename($p,'.zip');$j=db()->one('SELECT state FROM jobs WHERE id=?',[$id]);if(!in_array($j['state']??'',['queued','running'],true)){unlink($p);$n++;}}
        return $n;
    }
}
